<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\UserProfilePhoneNumberVO;

trait UserProfilePhoneNumberAttributeHolder
{
    protected UserProfilePhoneNumberVO|string|null $phoneNumber = null;
    protected bool $phoneNumberAssigned = false;

    public function getPhoneNumberOrCurrent(?UserProfilePhoneNumberVO $phoneNumber): ?UserProfilePhoneNumberVO
    {
        return $this->phoneNumberAssigned ? ($this->phoneNumber === null ? null : UserProfilePhoneNumberVO::from($this->phoneNumber)) : $phoneNumber;
    }
    public function phoneNumberTryBuildInitial(ConstraintFailList $error): ?UserProfilePhoneNumberVO
    {
        return  UserProfilePhoneNumberVO::tryFrom($this->phoneNumberAssigned ? $this->phoneNumber : null, $error);
    }
    public function phoneNumber(UserProfilePhoneNumberVO|string|null $phoneNumber): static
    {
        $this->phoneNumber = $phoneNumber;
        $this->phoneNumberAssigned = true;
        return $this;
    }
    public function getPhoneNumber(): ?string
    {
        return $this->phoneNumber instanceof UserProfilePhoneNumberVO ? $this->phoneNumber->value() : $this->phoneNumber;
    }
    public function isPhoneNumberAssigned(): bool
    {
        return $this->phoneNumberAssigned;
    }
    public function writePhoneNumberTo(mixed $att): void
    {
        if ($this->phoneNumberAssigned) {
            $att->phoneNumber($this->phoneNumber);
        }
    }
    public function readPhoneNumberFrom(mixed $att): void
    {
        if ($att->isPhoneNumberAssigned()) {
            $phoneNumber = $att->getPhoneNumber();
            $this->phoneNumber($phoneNumber);
        }
    }
    public function unsetPhoneNumber(): static
    {
        $this->phoneNumberAssigned = false;
        return $this;
    }
    protected function withDefaultPhoneNumber(): void
    {
    }
    protected function withAssertedPhoneNumberRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->phoneNumberAssigned = $this->phoneNumberAssigned) {
            $value->phoneNumber = UserProfilePhoneNumberVO::tryFrom($this->phoneNumber, $errorsList);
        }
    }
}
